const fs=require('node:fs'),vm=require('node:vm'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.join(__dirname,'..'),pairs=[[0,1],[0,2],[1,2]];
function setup(E,s,side,style,variant){
  if(style==='default'){E.auto(s,side,true);assert.equal(s.budget[side],0);assert.equal(s.pieces.filter(p=>p.side===side).reduce((n,p)=>n+p.learned.length,0),s.points);return;}
  const ps=s.pieces.filter(p=>p.side===side).sort((a,b)=>side==='red'?a.x-b.x:b.x-a.x),kinds=style==='defense'?['pawn','guard','elephant','horse','cannon','rook','king']:['rook','horse','cannon','pawn','guard','elephant','king'];
  let order=ps.filter(p=>p.kind!=='king').sort((a,b)=>kinds.indexOf(a.kind)-kinds.indexOf(b.kind));
  if(style==='mixed')order=['rook','pawn','guard','horse','cannon','elephant'].map(kind=>ps.find(p=>p.kind===kind));
  for(let i=0;i<order.length&&s.budget[side];i++){
    const p=order[i],ids=Object.keys(E.CARDS).filter(id=>E.CARDS[id].kind===p.kind);
    for(const index of style==='spread'?[(i+variant)%3]:pairs[variant])if(s.budget[side])E.learn(s,p.id,ids[index]);
  }
  assert.equal(s.budget[side],0);assert.equal(ps.reduce((n,p)=>n+p.learned.length,0),s.points);
  assert.equal(ps.filter(p=>p.learned.length).length,style==='spread'?s.points:s.points/2);
  assert(ps.every(p=>p.hp===18&&p.learned.length<3));
}

function engine(filename){const code=fs.readFileSync(path.join(root,filename),'utf8'),scripts=[...code.matchAll(/<script(?:[^>]*)>([\s\S]*?)<\/script>/g)].map(m=>m[1]),box={};vm.createContext(box);for(const script of scripts.slice(0,2))vm.runInContext(script,box);return {E:box.Yiwu,C:box.YiwuComputer};}
const rng=seed=>()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
function play(input,filename='github-release/index.html',trace=false,snapshotPly=null,opponentFile=null){
  const {E,C}=engine(filename),{scenario,seed,variant,style,aSide,baseline,comparator='spread'}=input,bSide=E.OTHER[aSide],s=E.create(scenario),random={[aSide]:rng(seed),[bSide]:rng(seed^0x9e3779b9)};
  const opponent=opponentFile?engine(opponentFile).C:C,controller=side=>side===aSide?C:opponent;
  setup(E,s,aSide,baseline?comparator:style,variant);setup(E,s,bSide,comparator,variant);E.start(s);
  const commands=[['create',scenario],...s.pieces.flatMap(p=>p.learned.map(id=>['learn',p.id,id])),['start']];let snapshot=null;
  const stats={moves:0,rests:0,battles:0,rounds:0,retreats:0,reversals:0,maxQuiet:0,cards:{red:0,black:0},decisionMs:0,maxDecisionMs:0};
  const lastMoves=new Map(),timeline=[];let steps=0;
  while(s.phase!=='ended'&&s.ply<600&&steps++<4200){
    if(s.phase==='board'){
      if(s.ply===snapshotPly)snapshot=JSON.parse(JSON.stringify(s));
      const started=performance.now(),action=controller(s.turn).board(s,random[s.turn],'standard'),ms=performance.now()-started;stats.decisionMs+=ms;stats.maxDecisionMs=Math.max(stats.maxDecisionMs,ms);
      const p=E.get(s,action.id),target=action.type==='move'?E.at(s,action.x,action.y):null;
      const entry={ply:s.ply+1,side:s.turn,type:action.type,id:p?.id,hp:p?.hp,from:p?[p.x,p.y]:null,to:action.type==='move'?[action.x,action.y]:null,score:action.score,quiet:s.quiet};
      if(trace)entry.ranked=controller(s.turn).rankedActions(s).slice(0,5);
      if(action.type==='pass'){E.pass(s);commands.push(['pass']);}
      else if(action.type==='rest'){stats.rests++;E.rest(s,action.id,action.card);commands.push(['rest',action.id,action.card]);}
      else{
        if(target){stats.battles++;entry.type='battle';entry.target=target.id;entry.targetHp=target.hp;lastMoves.delete(p.id);}
        else{stats.moves++;const last=lastMoves.get(p.id);if(last&&last[0]===action.x&&last[1]===action.y)stats.reversals++;lastMoves.set(p.id,[p.x,p.y]);}
        E.move(s,p.id,action.x,action.y);commands.push(['move',p.id,action.x,action.y]);
      }
      if(trace)timeline.push(entry);
    }else{
      const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),x=controller(a.side).combat(s,a.side,random[a.side],'standard');
      if(x==='retreat'){stats.retreats++;E.retreat(s);commands.push(['retreat']);}
      else{const y=controller(d.side).combat(s,d.side,random[d.side],'standard');for(const [p,id]of [[a,x],[d,y]])if(E.CARDS[id])stats.cards[p.side]++;E.resolve(s,x,y);commands.push(['resolve',x,y]);stats.rounds++;}
    }
    stats.maxQuiet=Math.max(stats.maxQuiet,s.quiet);
  }
  assert.equal(s.phase,'ended');
  return {input,plies:s.ply,winner:s.winner,reason:s.reason,...stats,...(trace?{timeline,commands,snapshot,final:s.pieces.map(p=>({id:p.id,kind:p.kind,hp:p.hp,x:p.x,y:p.y,learned:p.learned}))}:{})};
}
if(require.main===module){
  const data=require('./balance-v0671.json'),cases=data.runs.slice().sort((a,b)=>b.plies-a.plies).slice(0,3);
  const results=cases.map(input=>{const r=play(input,'github-release/index.html',true);assert.equal(r.plies,input.plies);assert.equal(r.winner,input.winner);console.log(JSON.stringify({...r,timeline:undefined,commands:undefined,final:undefined,snapshot:undefined}));return r;});
  fs.writeFileSync(path.join(__dirname,'long-trace-v0671.json'),JSON.stringify(results,null,2));
}
module.exports={engine,setup,play};

