const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {engine,setup}=require('../pace_v0672.cjs');
const source='work/balance-matrix-v0697/source.html',file=name=>__dirname+'/'+name,hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const label='yiwu-balance-matrix-0.6.97:20261111',styles=['default','spread','attack','defense','mixed'];
const seed=(scenario,style,comparator,replicate,role)=>crypto.createHash('sha256').update(`${label}:${scenario}:${style}:${comparator}:${replicate}:${role}`).digest().readUInt32LE(0);
function random(value){return()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296;};}
function inputs(scenario){
  const result=[];
  for(let i=0;i<styles.length;i++)for(let j=i+1;j<styles.length;j++){
    const style=styles[i],comparator=styles[j];
    for(let aVariant=0;aVariant<(style==='default'?1:3);aVariant++)for(let bVariant=0;bVariant<3;bVariant++)
      for(let replicate=0;replicate<2;replicate++)for(const aSide of ['red','black'])
        result.push({scenario,style,comparator,aVariant,bVariant,replicate,aSide,seedA:seed(scenario,style,comparator,replicate,'A'),seedB:seed(scenario,style,comparator,replicate,'B')});
  }
  for(let replicate=0;replicate<2;replicate++)for(const assignment of ['normal','swapped']){
    const a=seed(scenario,'default','default',replicate,'A'),b=seed(scenario,'default','default',replicate,'B');
    result.push({scenario,style:'default',comparator:'default',aVariant:0,bVariant:0,replicate,aSide:'red',assignment,seedA:assignment==='normal'?a:b,seedB:assignment==='normal'?b:a});
  }
  return result;
}
function state(E,input){
  const s=E.create(input.scenario),bSide=E.OTHER[input.aSide];
  setup(E,s,input.aSide,input.style,input.aVariant);setup(E,s,bSide,input.comparator,input.bVariant);
  assert.equal(s.budget.red,0);assert.equal(s.budget.black,0);assert(s.pieces.every(p=>p.hp===18&&p.learned.length<=2&&!p.exhausted.length));
  return s;
}
function play(input){
  const {E,C}=engine(source),s=state(E,input),bSide=E.OTHER[input.aSide];
  const rng={[input.aSide]:random(input.seedA),[bSide]:random(input.seedB)};
  const commands=[['create',s.scenario],...Array.from(s.pieces,p=>Array.from(p.learned,id=>['learn',p.id,id])).flat(),['start']];
  const pieceActivity=Object.fromEntries(Array.from(s.pieces,p=>[p.id,{side:p.side,kind:p.kind,cards:Array.from(p.learned),moves:0,rests:0,attacks:0,defenses:0,damage:0,captures:0,cardUses:0}])),initialHP=s.pieces.length*18;
  E.start(s);
  const stats={moves:0,rests:0,passes:0,battles:0,rounds:0,retreats:0,reversals:0},lastMoves=new Map();let steps=0;
  while(s.phase!=='ended'&&s.ply<600&&steps++<4200){
    if(s.phase==='board'){
      const action=C.board(s,rng[s.turn],'standard');
      if(action.type==='pass'){E.pass(s);commands.push(['pass']);stats.passes++;}
      else if(action.type==='rest'){E.rest(s,action.id,action.card);commands.push(['rest',action.id,action.card]);stats.rests++;pieceActivity[action.id].rests++;}
      else{
        const p=E.get(s,action.id),target=E.at(s,action.x,action.y),old=[p.x,p.y],last=lastMoves.get(p.id);
        if(target){stats.battles++;lastMoves.delete(p.id);pieceActivity[p.id].attacks++;pieceActivity[target.id].defenses++;}
        else{stats.moves++;pieceActivity[p.id].moves++;if(last&&last[0]===action.x&&last[1]===action.y)stats.reversals++;lastMoves.set(p.id,old);}
        E.move(s,p.id,action.x,action.y);commands.push(['move',p.id,action.x,action.y]);
      }
    }else{
      assert.equal(s.phase,'duel');const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),aId=C.combat(s,a.side,rng[a.side],'standard');
      if(aId==='retreat'){E.retreat(s);commands.push(['retreat']);stats.retreats++;}
      else{
        const dId=C.combat(s,d.side,rng[d.side],'standard'),hpA=a.hp,hpD=d.hp;
        E.resolve(s,aId,dId);commands.push(['resolve',aId,dId]);stats.rounds++;
        pieceActivity[a.id].damage+=hpD-(E.get(s,d.id)?.hp||0);pieceActivity[d.id].damage+=hpA-(E.get(s,a.id)?.hp||0);
        if(!E.get(s,d.id))pieceActivity[a.id].captures++;if(!E.get(s,a.id))pieceActivity[d.id].captures++;
        if(E.CARDS[aId])pieceActivity[a.id].cardUses++;if(E.CARDS[dId])pieceActivity[d.id].cardUses++;
      }
    }
  }
  assert.equal(s.phase,'ended','对局未自然结束，不能记为和局');assert.equal(stats.moves+stats.rests+stats.passes+stats.battles,s.ply);
  assert.equal(Object.values(pieceActivity).reduce((n,p)=>n+p.damage,0),initialHP-s.pieces.reduce((n,p)=>n+p.hp,0));
  return {input,winner:s.winner,reason:s.reason,plies:s.ply,...stats,pieceActivity,commands,terminalSHA256:hash(JSON.stringify(s))};
}
function allocations(E,scenario){
  const rows=[];
  for(const style of styles)for(let variant=0;variant<(style==='default'?1:3);variant++)for(const side of ['red','black']){
    const s=E.create(scenario);setup(E,s,side,style,variant);
    rows.push({style,variant,side,points:s.points,pieces:Array.from(s.pieces.filter(p=>p.side===side),p=>({id:p.id,kind:p.kind,x:p.x,y:p.y,cards:Array.from(p.learned)}))});
  }
  return rows;
}
if(require.main===module){
  const mode=process.argv[2];assert(['plan','quick','full'].includes(mode));
  if(mode==='plan'){
    assert(!fs.existsSync(file('plan.json')),'已有计划，不覆盖');fs.copyFileSync('github-release/index.html',file('source.html'),fs.constants.COPYFILE_EXCL);
    const plan={version:'0.6.97',sourceSHA256:hash(fs.readFileSync(source)),runnerSHA256:hash(fs.readFileSync(__filename)),sharedDriverSHA256:hash(fs.readFileSync(require.resolve('../pace_v0672.cjs'))),seedLabel:label,replicatesPerPair:2,limits:{plies:600,steps:4200},inputs:[...inputs('quick'),...inputs('full')]};
    assert.equal(plan.inputs.length,536);fs.writeFileSync(file('plan.json'),JSON.stringify(plan,null,2)+'\n');console.log('已固定 536 局：每模式 264 局交叉组合与 4 局默认控制。');
  }else{
    const plan=JSON.parse(fs.readFileSync(file('plan.json'))),output=file(mode+'.json');assert(!fs.existsSync(output),'已有运行结果，先核对原进程');
    assert.equal(plan.runnerSHA256,hash(fs.readFileSync(__filename)));assert.equal(plan.sharedDriverSHA256,hash(fs.readFileSync(require.resolve('../pace_v0672.cjs'))));assert.equal(plan.sourceSHA256,hash(fs.readFileSync(source)));
    const report={version:plan.version,sourceSHA256:plan.sourceSHA256,scenario:mode,allocations:allocations(engine(source).E,mode),runs:[],errors:[],completed:false},cases=plan.inputs.filter(r=>r.scenario===mode),save=()=>fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n');save();
    for(const input of cases){
      try{report.runs.push(play(input));}catch(error){report.errors.push({input,message:error.message});save();throw error;}
      assert.equal(plan.sourceSHA256,hash(fs.readFileSync(source)));save();if(report.runs.length%12===0)console.log(JSON.stringify({scenario:mode,finished:report.runs.length,total:cases.length}));
    }
    assert.equal(report.runs.length,cases.length);report.completed=true;save();
  }
}
module.exports={inputs,seed,random,state,play,allocations,hash,source,styles};

