const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {hash}=require('../balance-matrix-v06107/run.cjs'),file=n=>__dirname+'/'+n;
const read=n=>JSON.parse(fs.readFileSync(file(n+'.json'))),matrix=JSON.parse(fs.readFileSync('work/balance-matrix-v06107/analysis.json'));
function known(){
  const selected=read('inspection').rows.map(r=>matrix.reports.flatMap(r=>r.runs).find(g=>JSON.stringify(g.input)===JSON.stringify(r.input)));
  const solo=JSON.parse(fs.readFileSync('work/balance-matrix-v06107/solo-quick.json')).cases.map(r=>matrix.reports[0].runs.find(g=>JSON.stringify(g.input)===JSON.stringify(r.input)));selected.push(...solo);
  for(const report of matrix.reports)selected.push(report.runs.reduce((a,b)=>a.plies>=b.plies?a:b));
  const old=JSON.parse(fs.readFileSync('github-release/docs/data/two-round-capture-0.6.107.json')).reports.find(r=>r.group==='known').runs;
  const rook=old.find(r=>r.input.models.red==='candidate'&&r.winner!=='draw'&&Object.values(r.pieceActivity).filter(p=>p.side===r.winner&&p.damage>0).length===1&&Object.values(r.pieceActivity).some(p=>p.side===r.winner&&p.kind==='rook'&&p.damage>0));assert(rook);selected.push(rook);
  return [...new Map(selected.map(r=>{const {models,group,priorIndex,...input}=r.input;return [JSON.stringify(input),{...r,input}];})).values()];
}
const mode=process.argv[2];
if(mode==='plan'){
  assert(!fs.existsSync(file('plan.json')));assert.equal(known().length,13);
  const inputs=[],label='yiwu-pawn-target-0.6.108:20261111',seed=(g,s,r,side)=>crypto.createHash('sha256').update(`${label}:${g}:${s}:${r}:${side}`).digest().readUInt32LE(0);
  for(const [priorIndex,run]of known().entries())for(const model of ['baseline','candidate'])inputs.push({...run.input,group:'known',priorIndex,models:{red:model,black:model}});
  const pairs=[['default','default'],['spread','defense'],['attack','spread'],['mixed','defense']];
  for(const group of ['batch1','batch2'])for(const scenario of ['quick','full'])for(const [replicate,[style,comparator]]of pairs.entries())for(const [red,black]of [['baseline','baseline'],['candidate','baseline'],['baseline','candidate'],['candidate','candidate']])
    inputs.push({group,scenario,replicate,style,comparator,aVariant:style==='default'?0:replicate%3,bVariant:comparator==='default'?0:replicate%3,aSide:'red',seedA:seed(group,scenario,replicate,'red'),seedB:seed(group,scenario,replicate,'black'),models:{red,black}});
  const priorPlans=[...matrix.plan.priorSeedPlans,'balance-matrix-v06107'],priorSeeds=new Set();
  for(const folder of priorPlans)for(const row of JSON.parse(fs.readFileSync('work/'+folder+'/plan.json')).inputs){priorSeeds.add(row.seedA);priorSeeds.add(row.seedB);}
  assert.equal(priorSeeds.size,1024);const fresh=inputs.filter(i=>i.group!=='known');assert(fresh.every(i=>!priorSeeds.has(i.seedA)&&!priorSeeds.has(i.seedB)));assert.equal(new Set(fresh.flatMap(i=>[i.seedA,i.seedB])).size,32);assert.equal(inputs.length,90);
  const driver=fs.readFileSync('work/two-round-capture-v06107-final/driver.cjs','utf8').replaceAll('work/two-round-capture-v06107-final/baseline.html','work/pawn-target-v06108/baseline.html').replaceAll('work/two-round-capture-v06107-final/candidate.html','work/pawn-target-v06108/release.html');fs.writeFileSync(file('driver.cjs'),driver);
  const plan={version:'0.6.108',baselineVersion:'0.6.107',baselineCommit:'1d1a813929bcc81a0ca33068cd94a512169447bb',seedLabel:label,priorSeedPlans:priorPlans,priorSeedsChecked:priorSeeds.size,sourceSHA256:{baseline:hash(fs.readFileSync(file('baseline.html'))),candidate:hash(fs.readFileSync(file('release.html')))},driverSHA256:hash(driver),runnerSHA256:hash(fs.readFileSync(__filename)),limits:{plies:2000,steps:14000},inputs};
